@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbAdjacencyAggregateAliasSemanticsTest {
	private static final String NATIVE_PROPERTY = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String ADJACENCY = LmdbNativeAttemptMetrics.PATH_ADJACENCY_AGGREGATE;
	private static final String PREFERRED = ADJACENCY + "," + LmdbNativeAttemptMetrics.PATH_NESTED_LOOP;
	private static final String PATTERN = "?s <urn:alias-order:p> ?o . ";

	@Test
	void assignmentOrderMatchesOrdinaryEvaluation(@TempDir Path directory) {
		String previous = System.setProperty(NATIVE_PROPERTY, "true");
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig()
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL));
		SailRepository lmdb = new SailRepository(store);
		SailRepository memory = new SailRepository(new MemoryStore());
		try {
			lmdb.init();
			memory.init();
			populate(lmdb);
			populate(memory);
			assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			List<AliasCase> cases = List.of(
					new AliasCase("forward group aliases", "?a ?b", "COUNT(*)",
							"BIND(?a AS ?b) BIND(?s AS ?a)", false),
					new AliasCase("ordered group aliases", "?a ?b", "COUNT(*)",
							"BIND(?s AS ?a) BIND(?a AS ?b)", true),
					new AliasCase("forward count argument", "?s", "COUNT(?b)",
							"BIND(?a AS ?b) BIND(?s AS ?a)", false),
					new AliasCase("ordered distinct count argument", "?a", "COUNT(DISTINCT ?b)",
							"BIND(?s AS ?a) BIND(?a AS ?b)", true),
					new AliasCase("unbound source", "?s ?a ?b", "COUNT(?b)",
							"BIND(?missing AS ?a) BIND(?a AS ?b)", false),
					new AliasCase("forward constant alias", "?a ?b", "COUNT(*)",
							"BIND(?a AS ?b) BIND(<urn:alias-order:fixed> AS ?a)", false),
					new AliasCase("ordered constant alias", "?a ?b", "COUNT(*)",
							"BIND(<urn:alias-order:fixed> AS ?a) BIND(?a AS ?b)", true));
			for (AliasCase test : cases) {
				String query = test.query();
				Map<Map<String, Value>, Integer> expected = rows(memory, query, false, null);
				assertThat(expected).as(test.name()).isNotEmpty();
				assertThat(rows(lmdb, query, false, null)).as(test.name() + " ordinary LMDB").isEqualTo(expected);
				assertThat(rows(lmdb, query, true, null)).as(test.name() + " automatic LMDB").isEqualTo(expected);
				assertThat(rows(lmdb, query, true, PREFERRED)).as(test.name() + " preferred adjacency or fallback")
						.isEqualTo(expected);
				Observation observation = observe(lmdb, query, PREFERRED);
				if (test.adjacency()) {
					assertThat(rows(lmdb, query, true, ADJACENCY)).as(test.name() + " forced adjacency")
							.isEqualTo(expected);
					assertThat(observation.paths()).as(test.name() + " retains the adjacency optimization")
							.contains(ADJACENCY);
				} else {
					assertThat(observation.paths()).as(test.name() + " requires ordinary assignment semantics")
							.doesNotContain(ADJACENCY);
					// The sequential execution path names its grouping storage, while this decision names the strategy.
					assertThat(observation.decisions()).as(test.name() + " selects the ordinary fallback")
							.anySatisfy(decision -> assertThat(decision)
									.startsWith("winner=" + LmdbNativeAttemptMetrics.PATH_NESTED_LOOP + ";"));
				}
			}
		} finally {
			try {
				lmdb.shutDown();
			} finally {
				try {
					memory.shutDown();
				} finally {
					restore(previous);
				}
			}
		}
	}

	private static void populate(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var predicate = vf.createIRI("urn:alias-order:p");
			connection.begin();
			for (int i = 0; i < 5; i++) {
				connection.add(vf.createIRI("urn:alias-order:s" + i % 2), predicate,
						vf.createIRI("urn:alias-order:o" + i));
			}
			connection.commit();
		}
	}

	private static Map<Map<String, Value>, Integer> rows(SailRepository repository, String query,
			boolean nativeEnabled, String forced) {
		String previous = System.setProperty(NATIVE_PROPERTY, Boolean.toString(nativeEnabled));
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setLmdbResultCacheRequested(false);
			if (forced != null) {
				prepared.setForcedLmdbExecutionStrategy(forced);
			}
			Map<Map<String, Value>, Integer> bag = new HashMap<>();
			try (var result = prepared.evaluate()) {
				while (result.hasNext()) {
					Map<String, Value> values = new HashMap<>();
					result.next().forEach(binding -> values.put(binding.getName(), binding.getValue()));
					bag.merge(Map.copyOf(values), 1, Integer::sum);
				}
			}
			return bag;
		} finally {
			restore(previous);
		}
	}

	private static Observation observe(SailRepository repository, String query, String forced) {
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setLmdbResultCacheRequested(false);
			prepared.setForcedLmdbExecutionStrategy(forced);
			Set<String> paths = new HashSet<>();
			Set<String> decisions = new HashSet<>();
			collect(prepared.explain(Explanation.Level.Telemetry).toGenericPlanNode(), paths, decisions);
			return new Observation(paths, decisions);
		}
	}

	private static void collect(GenericPlanNode node, Set<String> paths, Set<String> decisions) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			paths.add(path);
		}
		String decision = node.getStringMetricActual(LmdbNativeExplain.DECISION_OUTCOME);
		if (decision != null) {
			decisions.add(decision);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collect(child, paths, decisions);
			}
		}
	}

	private static void restore(String previous) {
		if (previous == null) {
			System.clearProperty(NATIVE_PROPERTY);
		} else {
			System.setProperty(NATIVE_PROPERTY, previous);
		}
	}

	private record Observation(Set<String> paths, Set<String> decisions) {
	}

	private record AliasCase(String name, String groups, String aggregate, String assignments, boolean adjacency) {
		String query() {
			return "SELECT " + groups + " (" + aggregate + " AS ?n) WHERE { " + PATTERN + assignments
					+ " } GROUP BY " + groups;
		}
	}
}
